target.css:
:root {
  --night: #12202b;
  --panel: #1b2d39;
  --panel-deep: #142631;
  --line: #35505d;
  --muted: #91aab2;
  --text: #eef5ed;
  --mint: #78e0b3;
  --sun: #f6c65b;
  --blue: #76b9ef;
  --coral: #ef8d7c;
  --button: #d9f3df;
  --button-text: #17372f;
}

.grid-board {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  color: var(--text);
  background: var(--night);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.grid-board * {
  box-sizing: border-box;
}

.board-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 54px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
}

.mark {
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  color: var(--night);
  background: var(--mint);
  border-radius: 9px 9px 3px 9px;
  font-size: 16px;
  font-weight: 800;
}

.brand strong,
.brand small {
  display: block;
}

.brand strong {
  letter-spacing: 1.2px;
  font-size: 12px;
  line-height: 14px;
}

.brand small {
  color: var(--muted);
  font-size: 10px;
  line-height: 13px;
}

.header-meta {
  display: flex;
  align-items: center;
  gap: 9px;
}

.header-meta time {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.25px;
}

.live {
  padding: 4px 7px;
  color: var(--mint);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.board-main {
  display: grid;
  grid-template-columns: 1.16fr 0.84fr;
  gap: 10px;
  padding: 11px 14px;
}

.output-panel,
.diagnostics {
  min-width: 0;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.output-panel {
  padding: 11px 12px 10px;
}

.panel-kicker,
.diagnostic-title {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.9px;
}

.kw-line {
  display: flex;
  align-items: baseline;
  gap: 5px;
  margin: 1px 0 0;
}

.kw-line strong {
  color: var(--sun);
  font-size: 30px;
  font-weight: 750;
  line-height: 33px;
  letter-spacing: -1.4px;
}

.kw-line span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.output-note {
  margin: 0 0 7px;
  color: var(--mint);
  font-size: 10px;
  line-height: 13px;
}

.source-list {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.source-list li {
  display: grid;
  grid-template-columns: 70px 31px 1fr;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 12px;
}

.source-value {
  color: var(--text);
  font-weight: 700;
  text-align: right;
}

.track {
  display: block;
  height: 5px;
  overflow: hidden;
  background: var(--panel-deep);
  border-radius: 99px;
}

.fill {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.solar {
  width: 86%;
  background: var(--sun);
}

.battery {
  width: 49%;
  background: var(--mint);
}

.wind {
  width: 23%;
  background: var(--blue);
}

.diagnostics {
  padding: 11px 12px 10px;
}

.readouts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px 11px;
  margin: 9px 0 10px;
}

.readouts div {
  display: flex;
  justify-content: space-between;
  gap: 5px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
}

.readouts dt,
.readouts dd {
  margin: 0;
  font-size: 10px;
  line-height: 13px;
}

.readouts dt {
  color: var(--muted);
}

.readouts dd {
  color: var(--text);
  font-weight: 750;
}

.forecast {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 8px;
  background: var(--panel-deep);
  border-radius: 7px;
}

.forecast-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.forecast-value {
  color: var(--sun);
  font-size: 12px;
}

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 43px;
  padding: 8px 14px;
  background: var(--panel-deep);
  border-top: 1px solid var(--line);
}

.footer-note {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

.footer-note span {
  width: 6px;
  height: 6px;
  background: var(--mint);
  border-radius: 50%;
}

.dispatch-button {
  padding: 7px 10px;
  color: var(--button-text);
  background: var(--button);
  border: 0;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
  line-height: 14px;
}

